package com.sentinelcore.assetservice.service;
import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import com.sentinelcore.assetservice.dto.ComplianceSummaryResponse; import com.sentinelcore.assetservice.entity.*; import com.sentinelcore.assetservice.repository.*;
@Service public class ComplianceService { private final ComplianceFrameworkRepository frameworks; private final ComplianceControlRepository controls; private final ComplianceEvidenceRepository evidence; public ComplianceService(ComplianceFrameworkRepository f,ComplianceControlRepository c,ComplianceEvidenceRepository e){frameworks=f;controls=c;evidence=e;}
 @Transactional(readOnly=true) public List<ComplianceFramework> frameworks(){return frameworks.findAll();}
 @Transactional(readOnly=true) public List<ComplianceControl> controls(UUID frameworkId){return frameworkId==null?controls.findAll():controls.findByFrameworkId(frameworkId);}
 @Transactional(readOnly=true) public ComplianceSummaryResponse summary(UUID frameworkId){ComplianceFramework f=frameworks.findById(frameworkId).orElseThrow(); List<ComplianceControl> list=controls.findByFrameworkId(frameworkId); long compliant=list.stream().filter(x->x.getStatus()==ComplianceStatus.COMPLIANT).count(); long partial=list.stream().filter(x->x.getStatus()==ComplianceStatus.PARTIALLY_COMPLIANT).count(); long non=list.stream().filter(x->x.getStatus()==ComplianceStatus.NON_COMPLIANT).count(); long not=list.size()-compliant-partial-non; double percentage=list.isEmpty()?0:((compliant+partial*.5)/list.size())*100; return new ComplianceSummaryResponse(f.getId(),f.getName(),list.size(),compliant,partial,non,not,percentage);}
}